_COUNTY_OVERVIEW = "SELECT p.locationname AS county, p.measure, p.data_value,\n       s.rpl_themes AS svi_percentile, r.value AS rucc_code\nFROM public_data.cdc_places p\nLEFT JOIN public_data.svi_county s\n       ON s.county = p.locationname || ' County' AND s.st_abbr = p.stateabbr\nLEFT JOIN public_data.rucc_county r ON r.fips = s.fips AND r.attribute = 'RUCC_2023'\nWHERE p.measureid = %s AND p.stateabbr = %s AND p.data_value_type = 'Crude prevalence'\nORDER BY p.data_value DESC"


def _conn():
    return psycopg2.connect(
        host=os.getenv("PG_HOST", "127.0.0.1"), port=os.getenv("PG_PORT", "5432"),
        dbname=os.getenv("PG_DB_V3", "rain_v3"), user=os.getenv("PG_USER", "rain_app"),
        password=os.getenv("PG_PASSWORD", "rain_dev_pw"))


def _rows(sql, params=()):
    with _conn() as c, c.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
        cur.execute("SET TRANSACTION READ ONLY")
        cur.execute(sql, params)
        return [dict(r) for r in cur.fetchall()]


@router.get("/tables")
def tables():
    counts = _rows("""SELECT schemaname AS schema, relname AS table, n_live_tup AS approx_rows
                      FROM pg_stat_user_tables WHERE schemaname = ANY(%s)""", (list(TABLES),))
    by_key = {(r["schema"], r["table"]): r["approx_rows"] for r in counts}
    return [{"schema": s, "table": t, "columns": cols, "approx_rows": by_key.get((s, t))}
            for s, tbls in TABLES.items() for t, cols in tbls.items()]


@router.get("/views/county-overview")
def county_overview(state: str = "NV", measureid: str = "CHECKUP"):
    if not _COUNTY_OVERVIEW:
        raise HTTPException(404, "county overview needs cdc_places, svi_county and rucc_county")
    return _rows(_COUNTY_OVERVIEW, (measureid, state.upper()))


@router.get("/{schema}/{table}")
def table_rows(schema: str, table: str, request: Request,
               limit: int = 50, offset: int = 0, order_by: str = ""):
    cols = TABLES.get(schema, {}).get(table)
    if cols is None:
        raise HTTPException(404, f"unknown table {schema}.{table}")
    limit = max(1, min(int(limit), 500))
    where, params = [], []
    for key, value in request.query_params.items():
        if key in ("limit", "offset", "order_by"):
            continue
        if key not in cols:
            raise HTTPException(400, f"unknown filter column {key!r}")
        where.append(f'"{key}"::text = %s')
        params.append(value)
    order = order_by if order_by in cols else cols[0]
    sql = f'SELECT * FROM "{schema}"."{table}"'
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += f' ORDER BY "{order}" LIMIT %s OFFSET %s'
    return _rows(sql, (*params, limit, max(0, int(offset))))
